// Внешний модуль оплаты. В реальном проекте здесь был бы вызов внешнего
// платёжного провайдера (например, по HTTP). На момент лабораторной работы
// реальная интеграция ещё не реализована, поэтому модуль -- заглушка
// ("стаб"), которая имитирует случайный результат оплаты.
//
// В тестах этот модуль подменяется моком (jest.mock), чтобы не зависеть
// от случайности и не "тормозить" тестирование, как и рекомендовано
// методическими указаниями к лабораторной работе.

async function charge(amount) {
  if (amount <= 0) {
    throw new Error('Сумма к оплате должна быть положительной');
  }
  // Имитация недоступности реальной интеграции: считаем оплату успешной,
  // если сумма не превышает условный лимит "тестовой карты".
  const success = amount <= 100000;
  return {
    success,
    transactionId: success ? `TXN-${Date.now()}` : null,
  };
}

module.exports = { charge };
